export const THEMES=[{name:'Vale dos Dinossauros',sky:'#b9ebe2',hill:'#74bd9a',far:'#9ad6ba',soil:'#bd815f',grass:'#3d926c',accent:'#ffcc61'},{name:'Dunas dos Fósseis',sky:'#ffdcaf',hill:'#e6aa79',far:'#f2c698',soil:'#be7355',grass:'#cd885b',accent:'#a9e8d3'},{name:'Vulcão da Lua',sky:'#aaa3d5',hill:'#7777b5',far:'#9294c4',soil:'#68639b',grass:'#a6c4e2',accent:'#ffe29a'}];
export const overlap=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
export function makeLevel(index=0){const platforms=[],coins=[],enemies=[],spikes=[];const floor=(x,w)=>platforms.push({x,y:480,w,h:600,ground:true});floor(0,680);floor(780,650);floor(1540,620);floor(2270,650);floor(3030,650+index*160);const ledges=[[270,370,150],[480,285,130],[900,375,150],[1170,300,140],[1660,380,150],[1880,295,130],[2410,380,140],[2650,300,140],[3100,370,140],[3350,290,140]];for(const[x,y,w]of ledges)platforms.push({x,y,w,h:24});for(const p of platforms){if(p.ground){for(let x=p.x+90;x<p.x+p.w-55;x+=150)coins.push({x,y:433,r:12,taken:false})}else for(let x=p.x+25;x<p.x+p.w-10;x+=38)coins.push({x,y:p.y-35,r:12,taken:false})}for(const x of[680,1430,2160,2920])for(let k=0;k<4;k++)coins.push({x:x+12+k*25,y:370-Math.sin(k/3*Math.PI)*36,r:12,taken:false});for(const[x,a,b]of[[1050,820,1380],[1770,1580,2090],[2520,2320,2860],[3250,3060,3500+index*100]])enemies.push({x,y:448,w:36,h:32,a,b,v:(index+1)*12+40,alive:true});if(index>0)spikes.push({x:180,y:458,w:40,h:22});const end=3560+index*160;return {index,platforms,coins,enemies,spikes,end,checkpoint:{x:2340,y:438},length:end+180}}
export class Game{
 constructor(){this.start(0)}
 start(index=0,{coins=0,deaths=0}={}){this.level=makeLevel(index);this.player={x:70,y:430,w:30,h:44,vx:0,vy:0,ground:false,face:1};this.coins=coins;this.deaths=deaths;this.time=0;this.checkpoint=false;this.status='playing';this.invincible=0;this.coyote=0;this.buffer=0;this.jumpWas=false;this.events=[]}
 respawn(){this.deaths++;const p=this.player;p.x=this.checkpoint?this.level.checkpoint.x:70;p.y=420;p.vx=p.vy=0;this.invincible=1.4;this.coyote=this.buffer=0;this.events.push({type:'hurt'})}
 update(dt,input={}){this.events=[];if(this.status!=='playing')return;dt=Math.max(0,Math.min(1/30,Number(dt)||0));if(!dt)return;this.time+=dt;this.invincible=Math.max(0,this.invincible-dt);const p=this.player,lv=this.level;const jump=!!input.jump;if(jump&&!this.jumpWas)this.buffer=.14;this.jumpWas=jump;this.buffer=Math.max(0,this.buffer-dt);this.coyote=p.ground?.12:Math.max(0,this.coyote-dt);const dir=Math.max(-1,Math.min(1,Number(input.move)||0)),speed=input.run?310:240;p.vx+=(dir*speed-p.vx)*Math.min(1,dt*(p.ground?18:10));if(dir)p.face=dir;if(this.buffer>0&&this.coyote>0){p.vy=-560;p.ground=false;this.coyote=this.buffer=0;this.events.push({type:'jump'})}if(!jump&&p.vy<-220)p.vy+=1800*dt;p.vy=Math.min(850,p.vy+1350*dt);p.x+=p.vx*dt;for(const b of lv.platforms)if(overlap(p,b)){if(p.vx>0)p.x=b.x-p.w;else if(p.vx<0)p.x=b.x+b.w;p.vx=0}p.x=Math.max(0,Math.min(lv.length-p.w,p.x));const oldBottom=p.y+p.h;p.y+=p.vy*dt;p.ground=false;for(const b of lv.platforms)if(overlap(p,b)){if(p.vy>=0&&oldBottom<=b.y+2){p.y=b.y-p.h;p.vy=0;p.ground=true}else if(p.vy<0){p.y=b.y+b.h;p.vy=0}}for(const c of lv.coins)if(!c.taken&&Math.hypot(p.x+p.w/2-c.x,p.y+p.h/2-c.y)<29){c.taken=true;this.coins++;this.events.push({type:'coin',x:c.x,y:c.y})}for(const e of lv.enemies){if(!e.alive)continue;e.x+=e.v*dt;if(e.x<e.a||e.x+e.w>e.b){e.x=Math.max(e.a,Math.min(e.b-e.w,e.x));e.v*=-1}if(overlap(p,e)){if(p.vy>0&&oldBottom<e.y+15){e.alive=false;p.vy=-350;this.events.push({type:'stomp',x:e.x,y:e.y})}else if(!this.invincible){this.respawn();return}}}if(lv.spikes.some(s=>overlap(p,s))&&!this.invincible){this.respawn();return}if(p.y>750){this.respawn();return}if(!this.checkpoint&&p.x>lv.checkpoint.x){this.checkpoint=true;this.events.push({type:'checkpoint'})}if(p.x>lv.end){this.status='won';this.events.push({type:'win'})}}
}
